inline int homax(int a,int b)
{
    if(a > b) return a;
    return b;
}
inline int homin(int a,int b)
{
    if(a > b) return b;
    return a;
}
using namespace std;
bool vis[MAXN*2];
vector<int> sv;
vector<int> G[MAXN*2];
bool dfs(int x)
{
    if(vis[x^1]) return false;
    if(vis[x]) return true;
    vis[x] = true;
    sv.push_back(x);
    for(auto to : G[x])
    {
        if(!dfs(to)) return false;
    }
    return true;
}
void addcons(int x,int vx,int y,int vy)
{
    G[(x << 1 | vx)^1].push_back(y << 1 | vy);
    G[(y << 1 | vy)^1].push_back(x << 1 | vx);
    return ;
}
int N,M;
bool sat2()
{
    osu(1,N,i)
    {
        if(vis[i << 1] || vis[i << 1 | 1]) continue;
        sv.clear();//假定为真的dfs之前清空记录
        if(!dfs(i << 1))
        {
            while(!sv.empty()) vis[sv.back()] = false, sv.pop_back();
            if(!dfs(i << 1 | 1))
            {
                return false;
            }
        }
    }
    return true;
}
int main()
{
    scanf("%d%d",&N,&M);
    osu(1,M,i)
    {
        int a,b,c,d;
        scanf("%d%d%d%d",&a,&b,&c,&d);
        addcons(a,b,c,d);
    }
    if(sat2())
    {
        cout << "POSSIBLE" << endl;
        osu(1,N,i)
        {
            if(vis[i << 1])
            {
                cout << 0 << " ";
            }else{
                cout << 1 << " ";
            }
        }
    }else{
        cout << "IMPOSSIBLE" << endl;
    }
    return 0;
}
