完整代码:

```cpp
#include <iostream>
#include <cstdio>
#include <cstring>
#include <vector>
#define lson (o << 1)
#define rson (o << 1|1)
#define mid ((l+r)>>1)
#define MAXN 50005
#define m 201314
using namespace std;
int fa[MAXN],son[MAXN],siz[MAXN];
int l[MAXN],dep[MAXN],top[MAXN];
vector<int> stb[MAXN],edb[MAXN];
int st[MAXN],ed[MAXN];
int N,M,R;
int z[MAXN];
struct Edge{
	int to,ne;
}e[MAXN *2];
struct Segtree
{
	int val,lazy;
}tree[MAXN*4];
int head[MAXN];
int ecnt = 0;
void addedge(int x,int y)
{
	e[++ecnt].to = y;
	e[ecnt].ne = head[x];
	head[x] = ecnt;
	return;
}
void pushdown(int l,int r,int o)
{
	tree[lson].val += (mid-l+1)*tree[o].lazy%m;
	tree[lson].lazy += tree[o].lazy%m;
	tree[rson].val += (r-mid)*tree[o].lazy%m;
	tree[rson].lazy += tree[o].lazy%m;
	tree[o].lazy = 0;
	return;
}
void update(int ql,int qr,int l,int r,int o)
{
	if(ql > r || qr <l)
	{
		return;
	}
	if(ql <= l && qr >= r)
	{
		tree[o].lazy += 1;
		tree[o].val += (r-l+1);
		return;
	}
	pushdown(l,r,o);
	update(ql,qr,l,mid,lson);
	update(ql,qr,mid+1,r,rson);
	tree[o].val = (tree[lson].val%m + tree[rson].val%m)%m;
	return;
}
int query(int ql,int qr,int l,int r,int o)
{
	if(ql > r || qr < l)
	{
		return 0;
	}
	if(qr >= r && ql <= l)
	{
		return tree[o].val;
	}
	pushdown(l,r,o);
	return (query(ql,qr,l,mid,lson)%m + query(ql,qr,mid+1,r,rson)%m)%m;
}
void dfs1(int x)
{
	siz[x] = 1;
	for(int i = head[x];i;i=e[i].ne)
	{
		int to = e[i].to;
		if(to == fa[x])
		{
			continue;
		}
		if(son[x] = -1)son[x] = to;
		else if(siz[to] > siz[son[x]])
		{
			son[x] = to;
		}
		fa[to] = x;
		dep[to] = dep[x]+1;
		dfs1(to);
		siz[x] +=siz[to];
	}
	return;
}
int xu = 0;
void dfs2(int x,int ttop)
{
	//cout << x << endl;
	l[x] = ++xu;
	top[x] = ttop;
	if(son[x] != -1)
		dfs2(son[x],ttop);
	for(int i = head[x];i;i = e[i].ne)
	{
		int to = e[i].to;
		if(to == son[x] || to == fa[x])
		{
			continue;
		}
		dfs2(to,to);
	}
	return;
}
inline void mswap(int &a,int &b)
{
	int t = a;
	a = b;
	b = t;
	return;
}
void poadd(int x,int y)
{
	while(top[x] != top[y])
	{
		if(dep[top[x]] < dep[top[y]])
		{
			mswap(x,y);
		}
		update(l[top[x]],l[x],1,N,1);
		x = fa[top[x]];
	}
	if(dep[x] < dep[y])
	{
		mswap(x,y);
	}
	update(l[y],l[x],1,N,1);
	return;
}
int poque(int x,int y)
{
	int ans = 0;
	while(top[x] != top[y])
	{
		if(dep[top[x]] < dep[top[y]])
		{
			mswap(x,y);
		}
		ans += query(l[top[x]],l[x],1,N,1);
		ans = ans%m;
		x = fa[top[x]];
	}
	if(dep[x] < dep[y])
	{
		mswap(x,y);
	}
	ans += query(l[y],l[x],1,N,1);
	ans %= m;
	return ans;
}
void read(int &s)
{
	s=0;char ch=getchar();
	while(ch<'0'||ch>'9')ch=getchar();
	while(ch>='0'&&ch<='9'){s=s*10+ch-'0';ch=getchar();}
	return;
}
int fm(int a)
{
	int s = a;
	while(s<0)s+=m;
	return s;
}
int main()
{
	//freopen("4211.in","r",stdin);
	memset(siz,0,sizeof(siz));
	memset(top,-1,sizeof(top));
	memset(son,-1,sizeof(son));
	memset(l,0,sizeof(l));
	memset(dep,0,sizeof(dep));
	memset(fa,-1,sizeof(fa));
	read(N);read(M);
	R = 0;
	for(int i = 1;i <= N-1;i++)
	{
		int ed;
		read(ed);
		addedge(i,ed);
		addedge(ed,i);
	}
	for(int i = 0;i < M;i++)
	{
		int op,ed;
		read(op);
		read(ed);
		read(z[i]);
		stb[op-1].push_back(i);
		edb[ed].push_back(i);
	}
	dfs1(R);
	//cout << "1!" << endl;
	dfs2(R,R);
	//cout << "2!" << endl;
	for(int i = 0;i < N;i++)
	{
		poadd(0,i);
		for(int j = 0;j < stb[i].size();j++)
		{
			st[stb[i][j]] = poque(0,z[stb[i][j]]);
		}
		for(int j = 0;j < edb[i].size();j++)
		{
			ed[edb[i][j]] = poque(0,z[edb[i][j]]);
		}
	}
	for(int i = 0;i < M-1;i++)
	{
		printf("%d\n",fm(ed[i]-st[i]));
	}
	printf("%d",fm(ed[M-1]-st[M-1]));
	//cout << poque(0,4);
}

