#define MAXN 1050
#define INF 0x3f3f3f3f
#define lovelive long long int
inline int homax(int a,int b)
{
    if(a > b) return a;
    return b;
}
inline int homin(int a,int b)
{
    if(a > b) return b;
    return a;
}
using namespace std;
vector<int> G[MAXN];
int DFN[MAXN],LOW[MAXN],iscut[MAXN];
bool vis[MAXN];
int xu = 0;
const int N = 1000;
bool inp[MAXN];
void tarjan(int x,int fa)
{
    DFN[x] = LOW[x] = ++xu;

    int cntz = 0;
    for(int i = 0;i < G[x].size();i++)
    {
        int to = G[x][i];
        if(!DFN[to])
        {
            tarjan(to,fa);
            LOW[x] = homin(LOW[x],LOW[to]);
            if(LOW[to] >= DFN[x] && x != fa) iscut[x] = 1;
            if(x == fa) cntz++;
        }
        LOW[x] = homin(LOW[x],DFN[to]);
    }
    if(cntz >= 2) iscut[x] = 1;
    return ;
}
void dfs(int x,int c)
{
    vis[x] = true;
    for(int i = 0;i < G[x].size();i++)
    {
        int to = G[x][i];
        if(to == c || vis[to]) continue;
        dfs(to,c);
    }
    return ;
}
int main()
{
    int tt = 0;
    while(true)
    {
        memset(inp,false,sizeof inp);
        for(int i = 0;i < MAXN;i++) G[i].clear();
        xu = 0;
        tt++;
        int a;
        scanf("%d",&a);
        if(a == 0) break;
        int b;
        scanf("%d",&b);
        G[a].push_back(b);
        G[b].push_back(a);
        inp[a] = inp[b] = true;
        while(true)
        {
            int a;
            scanf("%d",&a);
            if(a == 0) break;
            int b;
            scanf("%d",&b);
            G[a].push_back(b);
            G[b].push_back(a);
            inp[a] = inp[b] = true;
        }

        memset(DFN,0,sizeof DFN);
        memset(LOW,0,sizeof LOW);
        memset(iscut,0,sizeof iscut);
        for(int i = 1;i <= N;i++)
        {
            if(!inp[i]) continue;
            if(DFN[i] == 0) tarjan(i,i);
        }
        printf("Network #%d\n",tt);
        bool tb = false;
        for(int i = 1;i <= N;i++)
        {
            if(!inp[i]) continue;
            if(iscut[i])
            {
                tb = true;
                memset(vis,false,sizeof vis);
                int cnt = 0;
                for(int j = 1;j <= N;j++)
                {
                    if(!inp[j]) continue;
                    if(vis[j] == false && j != i)
                    {
                        cnt ++;
                        dfs(j,i);
                    }
                }
                printf("  SPF node %d leaves %d subnets\n",i,cnt);
            }
        }
        if(!tb)
        {
            printf("  No SPF nodes\n");
        }
        printf("\n");
    }
}
```

## 双连通分量

### 点双连通

点双连通(以下三条等价):

1. 该连通图的任意两条边存在一个包含这两条边的简单环；
2. 该连通图没有割点；
3. 对于至少3个点的图，若任意两点有至少两条点不重复路径。

点双连通分量(BCC)

点双连通分量构成对所有边集的一个划分。(一个点可能属于多个点双连通分量,而一个边恰好属于一个)

两个点双连通分量最多只有一个公共点，且必为割点。进一步地，所有点双与割点可抽象为一棵树结构。



不同BCC可能会有公共点,最多只有一个,即割点.任意割点都至少属于两个BCC.

去掉BCC中任意一个点,BCC仍联通.

求每个点双分量的方法类似tarjan,栈存的不是点而是边,因为一个点可能属于多个点双,出栈之后无法将这个点统计到其他点双中,而每个边一定都只属于一个点双.不过这样的点一定是割点,可以用栈存点+对割点特判,

