struct addedge
{
	int to,flow,cap,ne;
}e[MAXM << 1];
int head[MAXN];
int cur[MAXN];
int dep[MAXN];
int ecnt = -1;
int N,M,S,T;
void init()
{
	memset(head,-1,sizeof head);
	memset(dep,0,sizeof dep);
	return ;
}
void addedge(int u,int v,int cap)
{
	e[++ecnt].to = v;
	e[ecnt].flow = 0;
	e[ecnt].cap = cap;
	e[ecnt].ne = head[u];
	head[u] = ecnt;
	return ;
}
queue<int> q;
int bfs()
{
	memset(dep,0,sizeof dep);
	dep[S] = 1;
	q.push(S);
	while(!q.empty())
	{
		int nown = q.front();
		q.pop();
		for(int i = head[nown];i != -1;i = e[i].ne)
		{
			int to = e[i].to;
			if(dep[to] != 0 || e[i].flow >= e[i].cap) continue;
			dep[to] = dep[nown] + 1;
			q.push(to);
		}
	}
	return dep[T];
}
int homin(int a,int b)
{
	if(a < b) return a;
	return b;
