为了让删去的点值最小,要把点值反映到边权上,才能利用"最小"割求解
```cpp
#include <iostream>
#include <cstring>
#include <cstdio>
#include <queue>
#include <vector>
#define INF 2147483647
#define MAXN 10005
#define MAXM 100005
using namespace std;
struct addedge
{
	int to,flow,cap,ne;
}e[MAXM << 1];
int head[MAXN];
int cur[MAXN];
int dep[MAXN];
int ecnt = -1;
int N,M,S,T;
void init()
{
	memset(head,-1,sizeof head);
	memset(dep,0,sizeof dep);
	return ;
}
void addedge(int u,int v,int cap)
{
	e[++ecnt].to = v;
	e[ecnt].flow = 0;
	e[ecnt].cap = cap;
	e[ecnt].ne = head[u];
	head[u] = ecnt;
	return ;
}
queue<int> q;
int bfs()
{
	memset(dep,0,sizeof dep);
	dep[S] = 1;
	q.push(S);
	while(!q.empty())
	{
		int nown = q.front();
		q.pop();
		for(int i = head[nown];i != -1;i = e[i].ne)
		{
			int to = e[i].to;
			if(dep[to] != 0 || e[i].flow >= e[i].cap) continue;
			dep[to] = dep[nown] + 1;
			q.push(to);
		}
	}
	return dep[T];
}
int homin(int a,int b)
{
	if(a < b) return a;
	return b;
}
int dfs(int x,int fl)
{
	if(x == T) return fl;
	for(int &i = cur[x]; i != -1;i = e[i].ne)
	{
		int to = e[i].to;
		if(dep[to] != dep[x] + 1 || e[i].flow >= e[i].cap) continue;
		int f = dfs(to,homin(fl,e[i].cap - e[i].flow));
		if(f > 0)
		{
			e[i].flow += f;
			e[i^1].flow -= f;
			return f;
		}
	}
	return 0;
}
int Dinic()
{
	int ans = 0;
	while(bfs())
	{
		memcpy(cur,head,sizeof cur);
		while(int d = dfs(S,INF)) ans += d;
	}
	return ans;
}
int a[105][105];
int main()
{
	init();
	cin >> M >> N;
	S = N*M;
	T = N*M+1;
	int sum = 0;
	for(int i = 1;i <= M;i++)
	{
		for(int j = 1;j <= N;j++)
		{
			cin >> a[i][j];
			sum += a[i][j];
		}
	}
	for(int i = 1;i <= M;i++)
	{
		for(int j = 1;j <= N;j++)
		{
			int num = (i-1)*N + j-1;
			if((i+j) % 2 == 1)
			{
				addedge(S,num,a[i][j]);
				addedge(num,S,0);
				if(i > 1)
				{
					addedge(num,num-N,INF);
					addedge(num-N,num,0);
				}
				if(i < M)
				{
					addedge(num,num+N,INF);
					addedge(num+N,num,0);
				}
				if(j < N)
				{
					addedge(num,num+1,INF);
					addedge(num+1,num,0);
				}
				if(j > 1)
				{
					addedge(num,num-1,INF);
					addedge(num-1,num,0);
				}
			}else{
				addedge(num,T,a[i][j]);
				addedge(T,num,0);
			}
		}
	}
	cout << sum - Dinic() << endl;
	return 0;
}

